import{_ as s,o as i,c as a,ag as t}from"./chunks/framework.B7PviQjB.js";const k=JSON.parse('{"title":"Deploy to production","description":"Build the backend image and the frontend with your own URLs, run migrations, connect storage, and turn on access control.","frontmatter":{"title":"Deploy to production","description":"Build the backend image and the frontend with your own URLs, run migrations, connect storage, and turn on access control.","type":"how-to"},"headers":[],"relativePath":"developers/self-hosting/deploy.md","filePath":"developers/self-hosting/deploy.md"}'),n={name:"developers/self-hosting/deploy.md"};function o(l,e,h,d,r,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="deploy-to-production" tabindex="-1">Deploy to production <a class="header-anchor" href="#deploy-to-production" aria-label="Permalink to &quot;Deploy to production&quot;">​</a></h1><p>Build the backend image and the frontend with your own URLs, run migrations, connect storage, and turn on per-document access control.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Run PostgreSQL, a Yorkie server with a project for Wafflebase, and an S3-compatible object store yourself. The image contains the backend only.</li><li>Have a domain for the frontend and one for the backend, with TLS, and a GitHub OAuth app. See <a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a>.</li><li>Have the Yorkie admin CLI (<code>yorkie</code>) to register webhooks.</li></ul></div><h2 id="build-and-run-the-backend-image" tabindex="-1">Build and run the backend image <a class="header-anchor" href="#build-and-run-the-backend-image" aria-label="Permalink to &quot;Build and run the backend image&quot;">​</a></h2><ol><li><p>From the repository root, build the image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase-backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div></li><li><p>Run it with your configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:3000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase-backend</span></span></code></pre></div></li></ol><p>The image runs <code>node dist/main</code> on port <code>3000</code> and sets <code>NODE_ENV=production</code>. It bundles the DuckDB extensions the lakehouse connector needs, so it needs no internet access for them. It is based on Debian (<code>node:22-bookworm-slim</code>), not Alpine. For the variables to put in <code>backend.env</code>, see <a href="/docs/developers/self-hosting/configuration.html">Configuration</a>.</p><h2 id="run-database-migrations" tabindex="-1">Run database migrations <a class="header-anchor" href="#run-database-migrations" aria-label="Permalink to &quot;Run database migrations&quot;">​</a></h2><ol><li><p>Apply pending migrations before the new image serves traffic. From a checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @wafflebase/backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prisma</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Or as a one-off job or init container using the image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app/packages/backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prisma@6.6.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div></li></ol><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Do not run <code>pnpm backend migrate</code> against production. It runs <code>prisma migrate dev</code>, which can create migration files and offer to reset the database.</p></div><h2 id="build-the-frontend" tabindex="-1">Build the frontend <a class="header-anchor" href="#build-the-frontend" aria-label="Permalink to &quot;Build the frontend&quot;">​</a></h2><p>The frontend&#39;s backend and Yorkie addresses are compiled in. A build with nothing configured points every browser at <code>http://localhost:3000</code>.</p><ol><li><p>Create <code>packages/frontend/.env.production.local</code> from the template <code>packages/frontend/.env.production.example</code>, and fill in your values:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VITE_BACKEND_API_URL=https://api.example.com</span></span>
<span class="line"><span>VITE_YORKIE_RPC_ADDR=https://yorkie.example.com</span></span>
<span class="line"><span>VITE_YORKIE_PUBLIC_KEY=your_yorkie_public_key</span></span></code></pre></div><p>In CI, pass the same variables on the build command instead. They override every file.</p></li><li><p>Build the app and the in-app documentation together:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:all</span></span></code></pre></div><p>The output is <code>packages/frontend/dist</code>, with the documentation at <code>dist/docs</code>. To build the app alone, run <code>pnpm core build</code> and then <code>pnpm frontend build</code>.</p></li><li><p>Check that your backend&#39;s host is in the app build. The <code>docs</code> directory is skipped because these pages mention example hosts:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exclude-dir=docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;api.example.com&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/frontend/dist</span></span></code></pre></div><p>It must print at least one file. Also check that <code>grep -rl --exclude-dir=docs &#39;api.wafflebase.io&#39; packages/frontend/dist</code> prints nothing.</p></li><li><p>Serve <code>packages/frontend/dist</code> from any static host or CDN, with a fallback to <code>index.html</code> for unknown paths.</p></li></ol><p>Use <code>.env.production.local</code>, not <code>.env.local</code>: <code>.env.local</code> ranks below <code>.env.production</code>. Ignore <code>api.yorkie.dev</code> in the build output; it is the Yorkie SDK&#39;s own default and is always present. For the full variable list, see <a href="/docs/developers/self-hosting/configuration.html#frontend-build-time-variables">Frontend: build-time variables</a>.</p><h2 id="set-up-blob-storage" tabindex="-1">Set up blob storage <a class="header-anchor" href="#set-up-blob-storage" aria-label="Permalink to &quot;Set up blob storage&quot;">​</a></h2><p>Wafflebase stores blobs in two S3-compatible buckets: one for uploaded files (<code>FILE_STORAGE_*</code>) and one for images embedded in documents (<code>IMAGE_STORAGE_*</code>).</p><ol><li>Create both buckets, for example <code>wafflebase-files</code> and <code>wafflebase-images</code>.</li><li>Give the backend&#39;s credentials object read and write access to them. If you skip step 1, the credentials also need <code>s3:CreateBucket</code>.</li><li>Set all five variables for each bucket (endpoint, bucket, region, access key, secret key). In production nothing falls back to MinIO.</li><li>Optional: set <code>FILE_STORAGE_PREFIX</code> or <code>IMAGE_STORAGE_PREFIX</code> to share a bucket with another app. Do not change a prefix after the first upload; existing objects stop resolving.</li></ol><p>At startup the backend checks each bucket and tries to create a missing one. A failure is logged as a warning and the server starts anyway; uploads then fail until storage works. If one bucket is misconfigured, only that feature stops working.</p><table tabindex="0"><thead><tr><th>Upload</th><th>Limit</th><th>Types</th></tr></thead><tbody><tr><td>File uploaded as a document</td><td>50 MB; 25 MB for images</td><td>Any file</td></tr><tr><td>Image inserted into a document</td><td>10 MB</td><td>PNG, JPEG, GIF, WebP</td></tr></tbody></table><p>These limits are fixed. An upload over the limit is refused with <code>413</code>, or with <code>400 File too large (max 25 MB)</code> for an image file between 25 MB and 50 MB. The editors downscale a larger image before inserting it, so the 10 MB limit rarely shows. Set your proxy&#39;s request body limit to at least 50 MB so it does not refuse uploads first.</p><h2 id="run-behind-a-tls-proxy" tabindex="-1">Run behind a TLS proxy <a class="header-anchor" href="#run-behind-a-tls-proxy" aria-label="Permalink to &quot;Run behind a TLS proxy&quot;">​</a></h2><ol><li>Set <code>BACKEND_TRUST_PROXY=1</code>, or your real number of proxy hops.</li><li>Set <code>GITHUB_CALLBACK_URL</code> to the <code>https://</code> URL users reach. If you cannot, set <code>COOKIE_SECURE=true</code>.</li><li>Set <code>FRONTEND_URL</code> to the frontend&#39;s public origin.</li><li>Set <code>WAFFLEBASE_API_ORIGIN</code> to the backend&#39;s public origin, the same value as <code>VITE_BACKEND_API_URL</code>.</li></ol><h2 id="turn-on-per-document-access-control" tabindex="-1">Turn on per-document access control <a class="header-anchor" href="#turn-on-per-document-access-control" aria-label="Permalink to &quot;Turn on per-document access control&quot;">​</a></h2><p>Browsers connect to Yorkie directly. Until you register the auth webhook, Yorkie checks no workspace membership or share-link role, and anyone who can reach it can open or change a document whose key they know.</p><ol><li><p>Set <code>YORKIE_SECRET_KEY</code> on the backend to your Yorkie project&#39;s secret key.</p></li><li><p>Register the auth webhook on the Yorkie project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yorkie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin-use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rpc-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yorkie.example.com:443</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yorkie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com/internal/yorkie/auth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AttachDocument</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PushPull</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DetachDocument</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Broadcast</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RemoveDocument</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ListRevisions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GetRevision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RestoreRevision</span></span></code></pre></div></li><li><p>Check the backend log. It says <code>yorkie auth webhook: enforcing per-document access</code>. This line reflects only <code>YORKIE_AUTH_WEBHOOK_ENFORCE</code>; it cannot tell whether step 2 was done.</p></li></ol><p>With <code>YORKIE_AUTH_WEBHOOK_ENFORCE</code> unset, access is enforced as soon as the methods are registered. Viewers can read a document but not change it, and only members and editors can see or restore its version history. To remove the webhook, run <code>yorkie project update &lt;project&gt; --auth-webhook-method-rm ALL</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not register <code>CreateRevision</code>. Yorkie sends it without a document, so registering it stops everyone, owners included, from naming a version in version history.</p></div><h3 id="watch-decisions-before-enforcing" tabindex="-1">Watch decisions before enforcing <a class="header-anchor" href="#watch-decisions-before-enforcing" aria-label="Permalink to &quot;Watch decisions before enforcing&quot;">​</a></h3><ol><li>Set <code>YORKIE_AUTH_WEBHOOK_ENFORCE=false</code> and restart. The log shows a <code>SHADOW mode</code> warning, and decisions are logged but never enforced.</li><li>Use the app and confirm the log shows no wrong denials.</li><li>Unset the variable and restart.</li></ol><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Shadow mode allows everything, including writes from viewer share links and reading or restoring version history. Do not leave a deployment in it.</p></div><h3 id="keep-the-documents-list-in-edit-order" tabindex="-1">Keep the documents list in edit order <a class="header-anchor" href="#keep-the-documents-list-in-edit-order" aria-label="Permalink to &quot;Keep the documents list in edit order&quot;">​</a></h3><ol><li><p>Register the event webhook so the documents list sorts by last edit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yorkie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --event-webhook-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com/internal/yorkie/events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --event-webhook-events-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DocumentRootChanged</span></span></code></pre></div></li></ol><p>The webhook URL can be an internal address the Yorkie server reaches; it does not need to be public.</p><h2 id="check-health" tabindex="-1">Check health <a class="header-anchor" href="#check-health" aria-label="Permalink to &quot;Check health&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Returns</th></tr></thead><tbody><tr><td><code>GET /health</code></td><td><code>200</code> while the process runs</td></tr><tr><td><code>GET /health/ready</code></td><td><code>200</code> when the database is reachable, <code>503</code> when it is not</td></tr></tbody></table><p>Use <code>/health</code> as the liveness probe and <code>/health/ready</code> as the readiness probe.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>The image does not include the frontend, PostgreSQL, Yorkie, or object storage.</li><li>Upload limits cannot be changed by configuration.</li><li>Back up PostgreSQL, Yorkie&#39;s data store, and both buckets together; each holds part of every document.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/self-hosting/configuration.html">Configuration</a> for every variable.</li><li><a href="/docs/developers/self-hosting/optional-features.html">Optional features</a> to add analytics, lakehouse, error tracking, or the public template gallery.</li><li><a href="/docs/developers/self-hosting/troubleshooting.html">Troubleshooting</a> for errors after deploying.</li><li><a href="https://github.com/wafflebase/wafflebase/blob/main/docs/design/yorkie-auth-webhook.md" target="_blank" rel="noreferrer">Yorkie auth webhook design</a> for how access decisions are made.</li></ul>`,39)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
